static void construct(BasicJsonType& j, typename BasicJsonType::number_float_t val) noexcept
{
    // replace infinity and NAN by null
    if (not std::isfinite(val))
    {
        j = BasicJsonType{};
    }
    else
    {
        j.m_type = value_t::number_float;
        j.m_value = val;
    }
    j.assert_invariant();
}

